 ŵďĂƐ ƉŽƐƐƵĞŵ Ƶŵ ŵĠƚŽĚŽ ĚĞŶŽŵŝŶĂĚŽ acquire Ğ Ƶŵ ŵĠƚŽĚŽ ĚĞŶŽŵŝŶĂĚŽ release.
class LockA {
 private int turn = 0
 public void acquire(int tid) {
      while (turn == (1 - tid));              
 }
 public void release(int tid) {
 turn = (1 - tid);
 }
}
 class LockB {
 public void acquire() {
 disableInterrupts();
 }
 public void release() {
 enableInterrupts();
 }
 }
